  await expect(fabStatus(page)).toHaveAttribute('data-status', 'pending-refs');
  await expect(fabStatus(page)).toHaveText('Complete the references.');
  /* Planned pieces keep stable ids; lengths show absence, never 0. */
  await expect(pieceRow(page, 'P1-IN')).toHaveCount(1);
