/* ------------------------------------------------------------------ *
 * 4. Bend mode
 * ------------------------------------------------------------------ */

test('fab-12: bend mode — one bar per pipe, straight/arc breakdown, gap not applied', async ({ page }) => {
  await setupCase3x35(page);
  await page.locator('[data-testid="pipe-comb-fab-mode-bend"]').click();
  await page.locator('#pipe-comb-fab-clr').fill('228.6');
  await page.locator('#pipe-comb-fab-gap').fill('2');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  /* Explicit module warning: the gap is not applied to a bent bar. */
  const warn = page.locator('[data-testid="pipe-comb-fab-warnings"] [data-code="weld_gap_not_applicable_bend"]');
  await expect(warn).toBeVisible();
  /* One bent bar per pipe (3), not 6 welded pups. */
  const pieces = page.locator('[data-testid="pipe-comb-fab-piece"]');
  await expect(pieces).toHaveCount(3);
  await expect(pieceRow(page, 'P1-BEND')).toHaveCount(1);
  /* Bar = straight 927.922697 + arc 139.643793 + straight 1127.922697
     = 2195.489187 mm — the weld gap is NOT deducted here. */
  await expect(pieceRow(page, 'P1-BEND').locator('td').nth(5)).toHaveText('2195.49 mm');
  /* Straight/arc breakdown is shown for the bent bar. */
  const detail = page.locator('[data-testid="pipe-comb-fab-detail"][data-piece-id="P1-BEND"]');
  await detail.locator('summary').click();
  const breakdown = await detail.textContent();
  expect(breakdown).toContain('927.92');
  expect(breakdown).toContain('139.64');
  expect(breakdown).toContain('1127.92');
  expect(breakdown).toContain('2195.49');
});

