test('fab-19: 20 unit cycles never drift Lin/Lout/CLR/gap/allowance or results', async ({ page }) => {
  await setupCase3x35(page);
  for (let i = 0; i < 20; i++) {
    await page.getByRole('button', { name: 'in', exact: true }).click();
    await page.getByRole('button', { name: 'mm', exact: true }).click();
  }
  await expect(page.locator('#pipe-comb-fab-lin')).toHaveValue('1000');
  await expect(page.locator('#pipe-comb-fab-lout')).toHaveValue('1200');
  await expect(page.locator('#pipe-comb-fab-gap')).toHaveValue('0');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  await expect(pieceRow(page, 'P3-OUT').locator('td').nth(5)).toHaveText('1255.9 mm');
});

test('fab-20: real editing in inches and back to mm', async ({ page }) => {
  await setupCase3x35(page);
  await page.getByRole('button', { name: 'in', exact: true }).click();
  /* Display converts: 1000 mm = 39.3701 in (4-decimal inch convention). */
  await expect(page.locator('#pipe-comb-fab-lin')).toHaveValue('39.3701');
  /* Real edit: 40 in = 1016 mm. P1-IN = 943.922697 mm = 37.162315 in. */
  await page.locator('#pipe-comb-fab-lin').fill('40');
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('37.1623 in');
  await page.getByRole('button', { name: 'mm', exact: true }).click();
  await expect(page.locator('#pipe-comb-fab-lin')).toHaveValue('1016');
  /* 1016 - 72.077303 = 943.922697 mm. */
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('943.92 mm');
});

test('fab-21: comma accepted, ambiguous mixes rejected on the new inputs', async ({ page }) => {
  await setupCase3x35(page);
  await page.locator('#pipe-comb-fab-lin').fill('1000,5');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'complete-warnings');
  /* 1000.5 - 72.077303 = 928.422697 mm. */
  await expect(pieceRow(page, 'P1-IN').locator('td').nth(5)).toHaveText('928.42 mm');
  /* Ambiguous point+comma mix: localized rejection, no reinterpretation. */
  await page.locator('#pipe-comb-fab-lin').fill('10.0,5');
  await expect(fabStatus(page)).toHaveAttribute('data-status', 'review');
  await expect(page.locator('[data-testid="pipe-comb-fab-cutlist"]')).toHaveCount(0);
});

